def sid(*nums): return [f'SD-S{x:03}' for x in nums]
def eid(n): return f'SD-E{n:03}'
def cid(n): return f'SD-C{n:03}'
def cite(n):
    s=sources[n-1]
    return f'[{s["publisher"]}: {s["title"]}]({s["url"]})'

entities=[]
def entity(n,name,kind,jurisdiction,summary,refs,roles,authority,constraints,incentives,path='actors.md',as_of=ASOF):
    entities.append(dict(id=eid(n),name=name,kind=kind,jurisdiction=jurisdiction,summary=summary,
      as_of=as_of,source_ids=sid(*refs),roles=roles,authority=authority,constraints=constraints,
      incentives=incentives,dossier_path='research/states-defense/'+path))

