scenarios=[]
def scenario(n,title,trigger,actors,refs,cs,branches,caveats):
    scenarios.append(dict(id=f'SD-X{n:03}',title=title,status='hypothesis',trigger=trigger,actors=[eid(x) for x in actors],source_ids=sid(*refs),claim_ids=[cid(x) for x in cs],branches=branches,caveats=caveats,dossier_path='research/states-defense/scenarios.md'))
scenario(1,'Autonomous maritime incident becomes an alliance crisis','An autonomous system causes harm in a disputed maritime encounter.',[1,2,5,25,31,37,55],[22,35,27],[12,15,28],[{'choice':'Preserve evidence and hold political consultation','next_state':'Incident investigation','effect':'Allows accident, misuse and state-order explanations to remain distinct.'},{'choice':'Attribute the event before evidence is strong','next_state':'Alliance confrontation','effect':'Public commitments can narrow diplomatic room.'},{'choice':'Agree a pause and incident review','next_state':'Managed competition','effect':'Risk falls if the pause is implemented.'}],['The trigger is invented.','No source says this specific event will occur.','Treaty trigger and response are separate decisions.'])
scenario(2,'AI advice converts uncertainty into nuclear alarm','During a conventional crisis, an AI tool interprets ambiguous warning as hostile nuclear intent.',[1,2,25,31,49,50,56,58],[7,8,15,39,40,49],[2,3,6,18,19,25],[{'choice':'Require independent assessment and confirm channels','next_state':'Uncertainty under review','effect':'Creates a chance to correct a false alarm.'},{'choice':'Trust a confident output despite weak evidence','next_state':'Nuclear crisis','effect':'Human decision makers increase alert or issue threats.'},{'choice':'Reaffirm limits and maintain dialogue','next_state':'Contained conventional crisis','effect':'Reduces concern about nuclear intent.'}],['Human control can coexist with poor human advice.','No automatic model-to-launch transition.','No operational launch procedure is modeled.'])
scenario(3,'Taiwan political change becomes a supply and security dispute','A future Taiwan government seeks closer PRC ties and proposes a restrictive technology policy.',[1,2,3,8,16],[16,17,30],[9,10,14,27],[{'choice':'Use domestic review and commercial negotiation','next_state':'Political and trade dispute','effect':'Supply restrictions may be amended or rejected.'},{'choice':'US treats the proposal as an immediate security loss','next_state':'Coercive diplomacy','effect':'Economic and military signals may interact.'},{'choice':'Agree narrow safeguards and trade continuity','next_state':'Managed adjustment','effect':'Political change can occur without war.'}],['A party label is not a policy prediction.','TSMC control, export permission and technical supply continuity require separate company research.','An election alone does not transfer sovereignty or mandate a chip cutoff.'])
scenario(4,'Rogue-model cyber event is mistaken for state action','A model-assisted or model-directed incident crosses borders while political tension is high.',[1,2,19,20,56,57],[15,37,48],[16,17,26],[{'choice':'Separate technical attribution from authorization','next_state':'Joint or parallel investigation','effect':'Keeps accident and unauthorized use plausible.'},{'choice':'Assume the model owner proves state intent','next_state':'Retaliation pressure','effect':'False attribution can intensify the crisis.'},{'choice':'Contain the affected system and exchange evidence','next_state':'Incident control','effect':'May enable a reciprocal pause.'}],['The rogue-model trigger is speculative.','Volt Typhoon sources do not establish rogue AI.','No technical attack methods are included.'])
scenario(5,'Conventional crisis threatens confidence in shared warning systems','A crisis disrupts a service used for both conventional operations and nuclear warning.',[1,2,11,49,50,51,58,59,60],[8,40,43,46],[18,19,22],[{'choice':'Explain limited intent through an established channel','next_state':'Verification and restraint','effect':'Can reduce fear if the explanation is credible.'},{'choice':'Infer preparation for a disarming attack','next_state':'Nuclear signaling crisis','effect':'Pressure rises despite uncertainty about intent.'},{'choice':'Restore service and negotiate mutual limits','next_state':'Reduced entanglement risk','effect':'Creates an exit if both sides accept the limits.'}],['This is a general causal scenario.','No specific system vulnerability or target is identified.','A nuclear outcome is possible in the hypothesis, not inevitable.'])

